int xf_rail_server_execute_result(bp_error_t bp_error, bp_error_t bp_error) { struct bp_error *err; if (!bp_error) { __assert_fail("context", "<stdin>", 220, &__PRETTY_FUNCTION__); } do { if (!bp_error) { __assert_fail("xfc", "RAIL exec error: execResult=%s NtError=0x%X\n", 221, &__PRETTY_FUNCTION__); } } while (0); err = (bp_error)->error; if (!err) { __assert_fail("xfc", "RAIL exec error: execResult=%s NtError=0x%X\n", 224, &__PRETTY_FUNCTION__); } do { if ((bp_error)->eof) { WLog_Print_dbg_tag("com.freerdp.client.x11", 4, 228, "<stdin>", &__func__, "xfc", bp_error->eof, "xfc", bp_error->error_code); freerdp_abort_connect_context(err); } } while (0); return 0; }